import random
from fractions import Fraction

def run_trial(seed: int) -> dict:
    random.seed(seed)

    def gaussian_elimination(A):
        m, n = len(A), len(A[0])
        for i in range(m):
            max_row = i
            for j in range(i+1, m):
                if abs(A[j][i]) > abs(A[max_row][i]):
                    max_row = j
            A[i], A[max_row] = A[max_row], A[i]
            pivot = A[i][i]
            if pivot == 0:
                continue
            for j in range(n):
                A[i][j] /= pivot
            for j in range(m):
                if j != i:
                    factor = A[j][i]
                    for k in range(n):
                        A[j][k] -= factor * A[i][k]
        rank = sum(1 for row in A if any(row))
        return rank

    def resolution_depth(phi):
        clauses = phi.split(' or ')
        assignment = {}
        depth = 0
        while True:
            new_assignment = False
            for clause in clauses:
                if all(lit not in assignment or assignment[lit] == -1 for lit in clause.split(' and ')):
                    for lit in clause.split(' and '):
                        if lit[0] != '~':
                            assignment[lit] = 1
                        else:
                            assignment[lit[1:]] = -1
                    new_assignment = True
            if not new_assignment:
                break
            depth += 1
        return depth

    def construct_lie_algebroid(phi):
        clauses = phi.split(' or ')
        n = len(clauses)
        m = sum(len(clause.split(' and ')) for clause in clauses)
        A = [[0] * (n + m) for _ in range(n)]
        for i, clause in enumerate(clauses):
            literals = clause.split(' and ')
            for j, lit in enumerate(literals):
                if lit[0] != '~':
                    A[i][j] = 1
                else:
                    A[i][n + j] = -1
        return gaussian_elimination(A)

    n_max = 40
    instances_tested = 0
    total_rank = 0
    total_depth = 0

